TASKS[5] = {'task_id': 'TASK-05', 'title': 'Daily Temperatures (Monotonic Stack (Next Greater Element))', 'time_limit_minutes': 25, 'difficulty': 'Easy', 'problem_statement': 'Solve the core placement problem: Daily Temperatures.\n\nGiven an array of integers temperatures represents the daily temperatures, return an array answer such that answer[i] is the number of days you have to wait after the ith day to get a warmer temperature. If there is no future day for which this is possible, keep answer[i] == 0.\n\nTechnical Requirements:\n- Implementation Language: Java 17+\n- Algorithmic Paradigm: Monotonic Stack (Next Greater Element)\n- Time Complexity Target: O(N) Time\n- Space Complexity Target: O(N) Auxiliary Space\n- Handle all edge cases: Strictly decreasing sequence (all answers 0), Strictly increasing sequence, All equal elements, Single element.', 'input_format': 'Standard placement problem parameters as typed in Java method signature.', 'output_format': 'Calculated optimal return value in Java primitive or object representation.', 'starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Monotonic Stack (Next Greater Element)\n    public int[] dailyTemperatures(int[] temperatures) {\n        // Write your solution here\n        return null;\n    }\n}', 'java_starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Monotonic Stack (Next Greater Element)\n    public int[] dailyTemperatures(int[] temperatures) {\n        // Write your solution here\n        return null;\n    }\n}', 'solution_code': 'import java.util.*;\n\npublic class Solution {\n    public int[] dailyTemperatures(int[] temperatures) {\n        int[] ans = new int[temperatures.length];\n        Deque<Integer> stack = new ArrayDeque<>();\n        for (int i = 0; i < temperatures.length; i++) {\n            while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) {\n                int idx = stack.pop();\n                ans[idx] = i - idx;\n            }\n            stack.push(i);\n        }\n        return ans;\n    }\n}', 'java_solution_code': 'import java.util.*;\n\npublic class Solution {\n    public int[] dailyTemperatures(int[] temperatures) {\n        int[] ans = new int[temperatures.length];\n        Deque<Integer> stack = new ArrayDeque<>();\n        for (int i = 0; i < temperatures.length; i++) {\n            while (!stack.isEmpty() && temperatures[i] > temperatures[stack.peek()]) {\n                int idx = stack.pop();\n                ans[idx] = i - idx;\n            }\n            stack.push(i);\n        }\n        return ans;\n    }\n}', 'test_cases': [{'input': 'nums = [standard sample array], target = [target value]', 'expected_output': 'Target calculated answer', 'explanation': 'Validates primary Monotonic Stack (Next Greater Element) logic under normal test constraints.'}, {'input': 'Corner case input: Strictly decreasing sequence (all answers 0)', 'expected_output': 'Valid boundary response', 'explanation': 'Validates boundary edge case resilience and memory bounds.'}], 'rubric': {'Correctness': '40 points (Passes all hidden automated test suites)', 'Time Complexity': '30 points (Meets O(N) Time)', 'Space Complexity': '20 points (Meets O(N) Auxiliary Space)', 'Code Quality': '10 points (Clean naming, Java 17+ idioms, error handling)'}}

