TASKS[18] = {'task_id': 'TASK-18', 'title': 'Lowest Common Ancestor of a Binary Tree (Lowest Common Ancestor (LCA) in Binary Trees)', 'time_limit_minutes': 35, 'difficulty': 'Medium', 'problem_statement': 'Solve the core placement problem: Lowest Common Ancestor of a Binary Tree.\n\nGiven a binary tree, find the lowest common ancestor (LCA) of two given nodes in the tree.\n\nTechnical Requirements:\n- Implementation Language: Java 17+\n- Algorithmic Paradigm: Lowest Common Ancestor (LCA) in Binary Trees\n- Time Complexity Target: O(N) Time\n- Space Complexity Target: O(H) Auxiliary Space\n- Handle all edge cases: p is direct parent of q, p and q on leaf levels, Binary Search Tree variation uses value comparison.', 'input_format': 'Standard placement problem parameters as typed in Java method signature.', 'output_format': 'Calculated optimal return value in Java primitive or object representation.', 'starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Lowest Common Ancestor (LCA) in Binary Trees\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        // Write your solution here\n        return null;\n    }\n}', 'java_starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Lowest Common Ancestor (LCA) in Binary Trees\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        // Write your solution here\n        return null;\n    }\n}', 'solution_code': 'public class Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode l = lowestCommonAncestor(root.left, p, q);\n        TreeNode r = lowestCommonAncestor(root.right, p, q);\n        if (l != null && r != null) return root;\n        return l != null ? l : r;\n    }\n}', 'java_solution_code': 'public class Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode l = lowestCommonAncestor(root.left, p, q);\n        TreeNode r = lowestCommonAncestor(root.right, p, q);\n        if (l != null && r != null) return root;\n        return l != null ? l : r;\n    }\n}', 'test_cases': [{'input': 'nums = [standard sample array], target = [target value]', 'expected_output': 'Target calculated answer', 'explanation': 'Validates primary Lowest Common Ancestor (LCA) in Binary Trees logic under normal test constraints.'}, {'input': 'Corner case input: p is direct parent of q', 'expected_output': 'Valid boundary response', 'explanation': 'Validates boundary edge case resilience and memory bounds.'}], 'rubric': {'Correctness': '40 points (Passes all hidden automated test suites)', 'Time Complexity': '30 points (Meets O(N) Time)', 'Space Complexity': '20 points (Meets O(H) Auxiliary Space)', 'Code Quality': '10 points (Clean naming, Java 17+ idioms, error handling)'}}

TASKS[19] = {'task_id': 'TASK-19', 'title': 'Rotting Oranges (Graph Traversal: Breadth-First Search (BFS))', 'time_limit_minutes': 35, 'difficulty': 'Medium', 'problem_statement': 'Solve the core placement problem: Rotting Oranges.\n\nYou are given an m x n grid where each cell has values 0 (empty), 1 (fresh), or 2 (rotten). Return the minimum number of minutes that must elapse until no cell has a fresh orange.\n\nTechnical Requirements:\n- Implementation Language: Java 17+\n- Algorithmic Paradigm: Graph Traversal: Breadth-First Search (BFS)\n- Time Complexity Target: O(R * C) Time\n- Space Complexity Target: O(R * C) Auxiliary Space\n- Handle all edge cases: No fresh oranges initially (return 0), Unreachable fresh orange (return -1), All oranges rotten initially.', 'input_format': 'Standard placement problem parameters as typed in Java method signature.', 'output_format': 'Calculated optimal return value in Java primitive or object representation.', 'starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Graph Traversal: Breadth-First Search (BFS)\n    public int orangesRotting(int[][] grid) {\n        // Write your solution here\n        return null;\n    }\n}', 'java_starter_code': 'import java.util.*;\n\npublic class Solution {\n    // TODO: Implement optimal solution using Graph Traversal: Breadth-First Search (BFS)\n    public int orangesRotting(int[][] grid) {\n        // Write your solution here\n        return null;\n    }\n}', 'solution_code': 'import java.util.*;\n\npublic class Solution {\n    public int orangesRotting(int[][] grid) {\n        int r = grid.length, c = grid[0].length, fresh = 0;\n        Queue<int[]> q = new LinkedList<>();\n        for (int i = 0; i < r; i++) {\n            for (int j = 0; j < c; j++) {\n                if (grid[i][j] == 2) q.offer(new int[]{i, j});\n                else if (grid[i][j] == 1) fresh++;\n            }\n        }\n        if (fresh == 0) return 0;\n        int mins = 0;\n        int[][] dirs = {{1,0}, {-1,0}, {0,1}, {0,-1}};\n        while (!q.isEmpty() && fresh > 0) {\n            int sz = q.size();\n            for (int i = 0; i < sz; i++) {\n                int[] cur = q.poll();\n                for (int[] d : dirs) {\n                    int ni = cur[0] + d[0], nj = cur[1] + d[1];\n                    if (ni >= 0 && ni < r && nj >= 0 && nj < c && grid[ni][nj] == 1) {\n                        grid[ni][nj] = 2;\n                        fresh--;\n                        q.offer(new int[]{ni, nj});\n                    }\n                }\n            }\n            mins++;\n        }\n        return fresh == 0 ? mins : -1;\n    }\n}', 'java_solution_code': 'import java.util.*;\n\npublic class Solution {\n    public int orangesRotting(int[][] grid) {\n        int r = grid.length, c = grid[0].length, fresh = 0;\n        Queue<int[]> q = new LinkedList<>();\n        for (int i = 0; i < r; i++) {\n            for (int j = 0; j < c; j++) {\n                if (grid[i][j] == 2) q.offer(new int[]{i, j});\n                else if (grid[i][j] == 1) fresh++;\n            }\n        }\n        if (fresh == 0) return 0;\n        int mins = 0;\n        int[][] dirs = {{1,0}, {-1,0}, {0,1}, {0,-1}};\n        while (!q.isEmpty() && fresh > 0) {\n            int sz = q.size();\n            for (int i = 0; i < sz; i++) {\n                int[] cur = q.poll();\n                for (int[] d : dirs) {\n                    int ni = cur[0] + d[0], nj = cur[1] + d[1];\n                    if (ni >= 0 && ni < r && nj >= 0 && nj < c && grid[ni][nj] == 1) {\n                        grid[ni][nj] = 2;\n                        fresh--;\n                        q.offer(new int[]{ni, nj});\n                    }\n                }\n            }\n            mins++;\n        }\n        return fresh == 0 ? mins : -1;\n    }\n}', 'test_cases': [{'input': 'nums = [standard sample array], target = [target value]', 'expected_output': 'Target calculated answer', 'explanation': 'Validates primary Graph Traversal: Breadth-First Search (BFS) logic under normal test constraints.'}, {'input': 'Corner case input: No fresh oranges initially (return 0)', 'expected_output': 'Valid boundary response', 'explanation': 'Validates boundary edge case resilience and memory bounds.'}], 'rubric': {'Correctness': '40 points (Passes all hidden automated test suites)', 'Time Complexity': '30 points (Meets O(R * C) Time)', 'Space Complexity': '20 points (Meets O(R * C) Auxiliary Space)', 'Code Quality': '10 points (Clean naming, Java 17+ idioms, error handling)'}}

